{
  "tasks": [
    {
      "task_id": "T1",
      "title": "统计各项目已完成任务数量并降序排列",
      "business_question": "各项目的已完成任务数量是多少？请按数量降序排列。仅分析状态为“已完成”的任务，不要包含其他状态。",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标“统计各项目的已完成任务数量并按数量降序排列”。删除此任务将无法提供项目维度的工作量分布视图，无法支持基于任务完成情况的资源或进度决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "completed_task_count"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "completed_task_count",
            "direction": "desc"
          }
        }
      ]
    }
  ]
}
